//     W <slotidx> <count> \n <hex>... : a vocab slot whose choice index is tied to slot slotidx (parallel list)
// Usage: bf spec.txt nproc [hashmode]
//   hashmode 0: fold32 of fnv1a64 (default); 1: fnv1a32; 2: low32 of fnv1a64; 3: high32
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
