static Str parsehex(const char *t){
    Str r; size_t n = strlen(t);
    while (n && (t[n-1]=='\n'||t[n-1]=='\r'||t[n-1]==' ')) n--;
    if (n==1 && t[0]=='-') { r.len=0; r.s=(unsigned char*)""; return r; }
    r.len = n/2; r.s = malloc(r.len+1);
    for (int i=0;i<r.len;i++) r.s[i] = hexval(t[2*i])*16+hexval(t[2*i+1]);
    r.s[r.len]=0; return r;
}

#define FNV_OFF 0xcbf29ce484222325ULL
#define FNV_PRIME 0x100000001b3ULL
#define FNV32_OFF 0x811c9dc5U
#define FNV32_PRIME 0x01000193U

static inline uint64_t upd(uint64_t h, const unsigned char *s, int n){
    if (hashmode==1){ uint32_t g=(uint32_t)h; for(int i=0;i<n;i++){ g^=s[i]; g*=FNV32_PRIME;} return g; }
    for (int i=0;i<n;i++){ h ^= s[i]; h *= FNV_PRIME; }
    return h;
