class Spec:
    def __init__(self, points):
        # points: list of (target_hex, [var strings])
        self.points = points
        self.slots = []
    def V(self, vocab):
        vocab = list(dict.fromkeys(vocab))
        self.slots.append(('V', vocab)); return len(self.slots) - 1
    def D(self, idx):
        self.slots.append(('D', idx)); return len(self.slots) - 1
    def R(self, ref):
        self.slots.append(('R', ref)); return len(self.slots) - 1
    def W(self, ref, vocab):
        self.slots.append(('W', ref, list(vocab))); return len(self.slots) - 1
    def size(self):
        n = 1
        for s in self.slots:
            if s[0] == 'V': n *= len(s[1])
        return n
    def write(self, path):
        nv = len(self.points[0][1])
        with open(path, 'w') as f:
            f.write('P %d %d\n' % (len(self.points), nv))
            for t, vs in self.points:
                f.write(t + ' ' + ' '.join(hx(v) for v in vs) + '\n')
            f.write('S %d\n' % len(self.slots))
            for s in self.slots:
                if s[0] == 'V':
                    f.write('V %d\n' % len(s[1]))
                    for v in s[1]: f.write(hx(v) + '\n')
                elif s[0] == 'D':
                    f.write('D %d\n' % s[1])
                elif s[0] == 'R':
                    f.write('R %d\n' % s[1])
                else:
                    f.write('W %d %d\n' % (s[1], len(s[2])))
                    for v in s[2]: f.write(hx(v) + '\n')
    def run(self, path, nproc=16, mode=0, show_partial=True):
        self.write(path)
        p = subprocess.run(['/tmp/core-hash/bf', path, str(nproc), str(mode)], capture_output=True, text=True)
        lines = [l for l in p.stdout.splitlines() if show_partial or l.startswith('FULL')]
        return lines, p.stderr

