// Solve for FNV-1a64 state h_prev given folded hashes of keys K_c = prefix + byte c (no suffix).
// usage: lastbyte fold_mode nproc c1 f1 c2 f2 ... (c as decimal byte value, f as hex)
// fold_mode: 0 = hi^lo, 1 = lo, 2 = hi
// Also supports "suffix" bytes: env SUFFIX=hex appended after the varying byte (known suffix).
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define P 0x100000001b3ULL
static int n; static unsigned cs[64]; static uint32_t fs[64];
static int mode;
static unsigned char suf[256]; static int sufn = 0;

static inline uint32_t fold(uint64_t h){
    if (mode==1) return (uint32_t)h;
    if (mode==2) return (uint32_t)(h>>32);
    return (uint32_t)(h>>32) ^ (uint32_t)h;
}
static inline uint64_t finish(uint64_t x){ // x = h_prev ^ c ; returns final hash
    uint64_t h = x * P;
    for (int i=0;i<sufn;i++){ h ^= suf[i]; h *= P; }
    return h;
}

int main(int argc, char **argv){
    mode = atoi(argv[1]); int nproc = atoi(argv[2]);
    n = (argc-3)/2;
    for (int i=0;i<n;i++){ cs[i]=atoi(argv[3+2*i]); fs[i]=(uint32_t)strtoul(argv[4+2*i],0,16); }
    char *s = getenv("SUFFIX");
    if (s){ sufn = strlen(s)/2; for (int i=0;i<sufn;i++){ unsigned v; sscanf(s+2*i,"%2x",&v); suf[i]=v; } }
    // inverse of 0x1b3 mod 2^32
    uint32_t inv = 1; for (int i=0;i<5;i++) inv *= 2 - 0x1b3*inv;
    for (int id=0; id<nproc; id++){
        if (fork()==0){
            uint64_t start = ((uint64_t)1<<32) * id / nproc, end = ((uint64_t)1<<32) * (id+1) / nproc;
            long cnt=0;
            for (uint64_t L=start; L<end; L++){
                uint32_t l = (uint32_t)L;
                if (sufn==0){
                    // derive u from first point
                    uint32_t xl = l ^ cs[0];
                    uint64_t prodlo = (uint64_t)xl * 0x1b3ULL; // up to 41 bits
                    uint32_t lo = (uint32_t)prodlo;
                    uint32_t carry = (uint32_t)(prodlo >> 32);
                    uint32_t hi;
                    if (mode==0) hi = fs[0] ^ lo; else if (mode==2) hi = fs[0]; else { if (lo != fs[0]) continue; hi = 0; }
                    if (mode==1){
                        // u unconstrained by lo; check others' lo only
                        int ok=1; for (int k=1;k<n;k++){ uint32_t x2=l^cs[k]; if ((uint32_t)(x2*0x1b3u)!=fs[k]) {ok=0;break;} }
                        if (ok){ printf("lo-solution l=%08x\n", l); cnt++; }
                        continue;
                    }
                    // hi = u*0x1b3 + carry + (xl & 0xffffff)<<8
                    uint32_t u = (hi - carry - ((xl & 0xffffffu) << 8)) * inv;
                    uint64_t hp = ((uint64_t)u << 32) | l;
