#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define P 0x100000001b3ULL
static uint64_t Pinv;
static unsigned char suf[256]; static int sufn;
static inline uint32_t fold(uint64_t h){ return (uint32_t)(h>>32) ^ (uint32_t)h; }
static inline uint64_t fwd(uint64_t t){ for (int i=0;i<sufn;i++){ t ^= suf[i]; t *= P; } return t; }
static inline uint64_t inv(uint64_t h){ for (int i=sufn-1;i>=0;i--){ h *= Pinv; h ^= suf[i]; } return h; }

int main(int argc, char **argv){
    int nproc = atoi(argv[1]); int nmin = atoi(argv[2]), nmax = atoi(argv[3]);
    char *sh = argv[4]; sufn = strcmp(sh, "-")==0 ? 0 : strlen(sh)/2;
    for (int i=0;i<sufn;i++){ unsigned v; sscanf(sh+2*i, "%2x", &v); suf[i]=v; }
    int nc = (argc-5)/2;
    uint64_t s[16]; uint32_t f[16];
    for (int i=0;i<nc;i++){ s[i]=strtoull(argv[5+2*i],0,16); f[i]=(uint32_t)strtoul(argv[6+2*i],0,16); }
    // inverse of P mod 2^64
    Pinv = 1; for (int i=0;i<7;i++) Pinv *= 2 - P*Pinv;
    int NN = nmax - nmin + 1;
    uint64_t *D = malloc(sizeof(uint64_t)*NN*16);
    uint64_t pn = 1; for (int i=0;i<nmin;i++) pn *= P;
    for (int k=0;k<NN;k++){
        for (int c=1;c<nc;c++) D[k*16+c] = (s[c]-s[0])*pn;
        pn *= P;
    }
    for (int id=0; id<nproc; id++){
        if (fork()==0){
            uint64_t start = ((uint64_t)1<<32)*id/nproc, end = ((uint64_t)1<<32)*(id+1)/nproc;
            for (uint64_t L=start; L<end; L++){
                uint32_t l=(uint32_t)L;
                uint64_t fin0 = ((uint64_t)(f[0]^l)<<32) | l;
                uint64_t t0 = inv(fin0);
                for (int k=0;k<NN;k++){
                    uint64_t t1 = t0 + D[k*16+1];
                    if (fold(fwd(t1)) != f[1]) continue;
                    int ok=1;
                    for (int c=2;c<nc;c++){ if (fold(fwd(t0 + D[k*16+c])) != f[c]) { ok=0; break; } }
                    if (ok){ printf("n=%d t0=%016llx (all %d contexts)\n", nmin+k, (unsigned long long)t0, nc); fflush(stdout); }
                    else if (nc==2) { printf("n=%d t0=%016llx (2 contexts)\n", nmin+k, (unsigned long long)t0); fflush(stdout); }
                }
            }
            _exit(0);
        }
    }
    while (wait(NULL)>0);
    return 0;
}

