// usage: mitm s0hex t0hex N midhex fileA fileB   (files: one hex-encoded string per line, '-' = empty)
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define P 0x100000001b3ULL
static uint64_t Pinv;
typedef struct { uint64_t st; uint32_t idx; uint32_t len; } Ent;
static int hexval(char c){ if(c>='0'&&c<='9')return c-'0'; if(c>='a'&&c<='f')return c-'a'+10; if(c>='A'&&c<='F')return c-'A'+10; return -1; }
static int parsehex(const char *t, unsigned char *out){
    int n=0; while (t[n] && t[n]!='\n' && t[n]!='\r') n++;
    if (n==1 && t[0]=='-') return 0;
    for (int i=0;i<n/2;i++) out[i]=hexval(t[2*i])*16+hexval(t[2*i+1]);
    return n/2;
}
static char **linesA; static int nA;
static uint64_t *htk; static int64_t *htv; static uint64_t hmask;

int main(int argc, char **argv){
    uint64_t s0 = strtoull(argv[1],0,16), t0 = strtoull(argv[2],0,16);
    int N = atoi(argv[3]);
    unsigned char mid[256]; int midn = parsehex(argv[4], mid);
    Pinv = 1; for (int i=0;i<7;i++) Pinv *= 2 - P*Pinv;
    FILE *fa = fopen(argv[5],"r"), *fb = fopen(argv[6],"r");
    static char line[1<<16]; unsigned char buf[1<<15];
    // count A
    int cap = 1<<20; linesA = malloc(sizeof(char*)*cap); nA=0;
    while (fgets(line,sizeof line,fa)){ if (nA==cap){cap*=2; linesA=realloc(linesA,sizeof(char*)*cap);} linesA[nA++]=strdup(line); }
    uint64_t hs = 1; while (hs < (uint64_t)nA*2) hs <<= 1; hmask = hs-1;
    htk = malloc(sizeof(uint64_t)*hs); htv = malloc(sizeof(int64_t)*hs);
    for (uint64_t i=0;i<hs;i++) htv[i]=-1;
    for (int i=0;i<nA;i++){
        int n = parsehex(linesA[i], buf);
        uint64_t h = s0;
        for (int k=0;k<n;k++){ h ^= buf[k]; h *= P; }
        for (int k=0;k<midn;k++){ h ^= mid[k]; h *= P; }
        uint64_t slot = (h * 0x9E3779B97F4A7C15ULL) >> 20 & hmask;
        while (htv[slot] != -1) slot = (slot+1) & hmask;
        htk[slot]=h; htv[slot]=((int64_t)n<<32) | i;
    }
    fprintf(stderr, "A loaded: %d\n", nA);
    long nb=0;
    while (fgets(line,sizeof line,fb)){
        int n = parsehex(line, buf); nb++;
        uint64_t h = t0;
        for (int k=n-1;k>=0;k--){ h *= Pinv; h ^= buf[k]; }
        uint64_t slot = (h * 0x9E3779B97F4A7C15ULL) >> 20 & hmask;
        while (htv[slot] != -1){
            if (htk[slot]==h){
                int la = (int)(htv[slot]>>32); int ia = (int)(htv[slot] & 0xffffffff);
                if (N < 0 || la + midn + n == N){
                    unsigned char ab[1<<15]; int an = parsehex(linesA[ia], ab);
                    printf("MATCH A=\""); for(int k=0;k<an;k++) putchar(ab[k]);
                    printf("\" MID=\""); for(int k=0;k<midn;k++) putchar(mid[k]);
                    printf("\" B=\""); for(int k=0;k<n;k++) putchar(buf[k]); printf("\"\n"); fflush(stdout);
                }
            }
            slot = (slot+1) & hmask;
        }
    }
    fprintf(stderr, "B processed: %ld\n", nb);
    return 0;
}

