import sys
M = (1 << 64) - 1
P = 0x100000001b3
def F(state, data):
    h = state
    for b in data:
        h ^= b
        h = (h * P) & M
    return h
def C(data, l):
    n = len(data)
    return (F(l, data) - l * pow(P, n, 1 << 64)) & M

def solve(t1s, t2s, x1, x2, kmax=80):
    x1 = x1.encode() if isinstance(x1, str) else x1
    x2 = x2.encode() if isinstance(x2, str) else x2
    assert len(x1) == len(x2)
    res = []
    for t1 in t1s:
        for t2 in t2s:
            d = (t2 - t1) & M
            for l in range(256):
                delta = (C(x2, l) - C(x1, l)) & M
                for k in range(kmax):
                    if (delta * pow(P, k, 1 << 64)) & M == d:
