"""Reproduces lini 1.1.0 `lini-gradient-XXXXXXXX` ids (black-box derived).

id  = hash8(key)
key = "linear {f4(angle)} {stops:?}"   for gradient()/linear-gradient()   (gradient() => angle 135)
key = "radial {stops:?}"               for radial-gradient()
where `stops` is the Rust Debug of a Vec<Value> of the *evaluated* stop arguments.
"""
import unicodedata

def hash8(s: str) -> str:
    h = 0xcbf29ce484222325
    for b in s.encode('utf-8'):
        h = ((h ^ b) * 0x100000001b3) & 0xffffffffffffffff
    return '%08x' % (((h >> 32) ^ h) & 0xffffffff)

def f4(v: float) -> str:                       # the program's SVG number formatter
    if v != v: return 'NaN'
    if v in (float('inf'), float('-inf')): return 'inf' if v > 0 else '-inf'
    s = '%.4f' % v                             # == Rust format!("{:.4}") (exact decimal rounding)
    if '.' in s: s = s.rstrip('0').rstrip('.')
    return '0' if s == '-0' else s

def f64_debug(v: float) -> str:                # Rust `{:?}` for f64
    if v != v: return 'NaN'
    if v == float('inf'): return 'inf'
    if v == float('-inf'): return '-inf'
    r = repr(v)                                # same shortest digits + same 1e-4 / 1e16 thresholds
    if 'e' in r:
        m, e = r.split('e')
        return '%se%d' % (m[:-2] if m.endswith('.0') else m, int(e))
    return r

def str_debug(s: str) -> str:                  # Rust `{:?}` for str (approximation for exotic Unicode)
    out = []
    for ch in s:
        o = ord(ch); cat = unicodedata.category(ch)
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\n': out.append('\\n')
        elif ch == '\r': out.append('\\r')
        elif ch == '\t': out.append('\\t')
        elif ch == '\0': out.append('\\0')
        elif cat in ('Cc', 'Cf', 'Cs', 'Co', 'Cn', 'Zl', 'Zp', 'Mn', 'Me') or (cat == 'Zs' and ch != ' '):
            out.append('\\u{%x}' % o)
        else: out.append(ch)
    return '"' + ''.join(out) + '"'

# Value constructors (evaluated stop values)
def Ident(s):   return ('Ident', s)        # named colours / bare words, as written (case kept)
def Number(x):  return ('Number', float(x))
def Percent(x): return ('Percent', float(x))
def Hex(s):     return ('Hex', s)          # digits without '#', case as written; oklch() -> lowercase hex
def Str(s):     return ('String', s)       # "quoted" strings (content, unescaped)
def Var(n, raw=False): return ('LiveVar', n, raw)   # --name  (name without the leading --)
def Tuple(*xs): return ('Tuple', list(xs))  # space-separated list, e.g. `red 20%`
def Call(name, *args): return ('Call', name, list(args))   # rgb()/hsl()/rgba()/hsla()/nested calls, args evaluated

def debug(v) -> str:
    k = v[0]
    if k == 'Ident':   return 'Ident(%s)' % str_debug(v[1])
    if k == 'Number':  return 'Number(%s)' % f64_debug(v[1])
    if k == 'Percent': return 'Percent(%s)' % f64_debug(v[1])
    if k == 'Hex':     return 'Hex(%s)' % str_debug(v[1])
    if k == 'String':  return 'String(%s)' % str_debug(v[1])
    if k == 'LiveVar': return 'LiveVar { name: %s, raw: %s }' % (str_debug(v[1]), 'true' if v[2] else 'false')
    if k == 'Tuple':   return 'Tuple([%s])' % ', '.join(debug(x) for x in v[1])
    if k == 'Call':    return 'Call(ResolvedCall { name: %s, args: [%s] })' % (str_debug(v[1]), ', '.join(debug(x) for x in v[2]))
    raise ValueError(k)

