    c = random.random()
    if c < 0.3: x = random.randint(-50, 400)
    elif c < 0.6: x = round(random.uniform(-500, 500), random.randint(1, 6))
    elif c < 0.8: x = random.choice([0.00001, 1e-7, 1e16, 123456789.123, 0.1, 2.5, 1e300])
    else: x = round(random.uniform(0, 1), 9)
    return x

def fmtnum(x):
    r = repr(float(x))
    return r

def rstop(depth=0):
    c = random.random()
    if c < 0.25:
        s = random.choice(colors); return s, Ident(s)
    if c < 0.4:
        n = random.choice(vars_); return '--' + n, Var(n)
    if c < 0.5:
        h = random.choice(['f00', 'F00', '00ff00', 'ABCDEF', 'abc8', '11223344']); return '#' + h, Hex(h)
    if c < 0.6:
        x = rnum(); return fmtnum(x), Number(float(fmtnum(x)))
    if c < 0.67:
        x = rnum(); return fmtnum(x) + '%', Percent(float(fmtnum(x)))
    if c < 0.75:
        s = random.choice(['a', 'hello world', 'quote"in', 'tab\there', 'ünï', '']);
        lit = '"' + s.replace('\\', '\\\\').replace('"', '\\"').replace('\t', '\\t') + '"'
        return lit, Str(s)
    if c < 0.85 and depth < 2:
        k = random.randint(2, 3)
        parts = [rstop_simple() for _ in range(k)]
        return ' '.join(p[0] for p in parts), Tuple(*[p[1] for p in parts])
    if depth < 2:
        name = random.choice(['rgb', 'rgba', 'hsl', 'hsla'])
        k = random.randint(0, 4)
        parts = [rstop_simple() for _ in range(k)]
        return '%s(%s)' % (name, ', '.join(p[0] for p in parts)), Call(name, *[p[1] for p in parts])
    s = random.choice(colors); return s, Ident(s)

def rstop_simple():
    c = random.random()
    if c < 0.3: s = random.choice(colors); return s, Ident(s)
    if c < 0.5: n = random.choice(vars_); return '--' + n, Var(n)
    if c < 0.8: x = rnum(); return fmtnum(x), Number(float(fmtnum(x)))
    x = rnum(); return fmtnum(x) + '%', Percent(float(fmtnum(x)))

ok = bad = err = 0
for i in range(int(sys.argv[2]) if len(sys.argv) > 2 else 60):
    n = random.randint(2, 5)
    stops = [rstop() for _ in range(n)]
    kind = random.choice(['gradient', 'linear-gradient', 'radial-gradient'])
    if kind == 'linear-gradient':
        ang = rnum()
        src = 'linear-gradient(%s, %s)' % (fmtnum(ang), ', '.join(s[0] for s in stops))
        want = linear_id(float(fmtnum(ang)), [s[1] for s in stops])
    elif kind == 'gradient':
        src = 'gradient(%s)' % ', '.join(s[0] for s in stops)
        want = linear_id(135, [s[1] for s in stops])
    else:
        src = 'radial-gradient(%s)' % ', '.join(s[0] for s in stops)
        want = radial_id([s[1] for s in stops])
    p = subprocess.run(['/workspace/executable', '-'], input=('|box| { fill: %s }\n' % src).encode(), capture_output=True, cwd='/tmp/core-hash')
    m = re.search(r'id="lini-gradient-([0-9a-f]+)"', p.stdout.decode(errors='replace'))
    if not m:
        err += 1
        print('ERR', src, p.stderr.decode()[:120].strip())
        continue
    if m.group(1) == want: ok += 1
    else:
        bad += 1; print('BAD', src, m.group(1), want)
print('ok', ok, 'bad', bad, 'err', err)
